async function followDraft(task,jobId){await refresh();const job=state.jobs.find(row=>row.job.id===jobId)?.job;let result;do{await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/api/draft/status',{task_id:task});}while(result.status==='running');sessionStorage.removeItem('waypoint-draft');if(result.status!=='complete')throw new Error(result.error || 'Drafting failed');if(!job)throw new Error('Job no longer available');showLetter(job,result.draft,result.digest);}
