  const started=await api('/api/documents/preview-start',{id:doc.id,page});let result;
  do{await new Promise(resolve=>setTimeout(resolve,500));result=await api('/api/documents/preview-status',{task_id:started.task_id});}while(result.status==='running');
  if(generation!==documentReviewGeneration)return;
  if(result.status!=='complete')throw new Error(result.error || 'PDF preview failed');
  const view=result.page;panel.replaceChildren(element('h3',`Visual review: ${doc.name}`),element('p',`Page ${view.page+1} of ${view.pages}. Check every page, including text, spacing and clipping.`));
  const image=document.createElement('img');image.alt=`Page ${view.page+1} of ${doc.name}`;image.src=`data:image/png;base64,${view.image}`;panel.append(image);
  const controls=element('div','','pdf-controls');
