async function followDiscovery(id){if(discoveryFollowing)return;discoveryFollowing=true;const progress=document.querySelector('#discovery-progress'),cancel=document.querySelector('#discovery-cancel'),resume=document.querySelector('#discovery-resume');cancel.hidden=false;resume.hidden=true;try{for(;;){const result=await api('/api/discover/status',{task_id:id});if(result.status==='failed'){sessionStorage.removeItem('waypoint-discovery');throw new Error(result.error || 'Discovery failed');}progress.textContent=`Boards processed: ${result.processed ?? 0} of ${result.total ?? '?'}`;if(result.summary){document.querySelector('#discovery-results').append(element('p',`${result.source}:${result.board} — ${result.summary}${result.source==='jobicy' ? (result.has_more===true ? ' · First 50 only; more matches may exist.' : ' · First page only; listings are from the last 7 days.') : ''}`));await refresh();}if(result.status==='complete'){sessionStorage.removeItem('waypoint-discovery');progress.textContent=result.cancelled?`Stopped after ${result.processed} of ${result.total} boards.`:`Finished ${result.processed} of ${result.total} boards.`;break;}await new Promise(resolve=>setTimeout(resolve,1000));}}catch(e){notify(e.message);if(e.message==='Discovery run not found')sessionStorage.removeItem('waypoint-discovery');if(sessionStorage.getItem('waypoint-discovery'))resume.hidden=false;}finally{discoveryFollowing=false;cancel.hidden=true;}}
