async function followDocumentReview(task){let result;do{await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/api/documents/suggest-status',{task_id:task});}while(result.status==='running');sessionStorage.removeItem('waypoint-document-review');if(result.status!=='complete')throw new Error(result.error || 'Document review failed');return result;}
function renderDocumentSuggestions(panel,result){panel.append(element('p',result.truncated?'Suggestions use the first 12,000 bytes of the document. Review each excerpt in context.':'Review each excerpt in context; selecting it attests that it is accurate.'));const options=[];for(const excerpt of result.excerpts){const label=element('label','','field-selection'),box=document.createElement('input');box.type='checkbox';box.value=excerpt;label.append(box,document.createTextNode(` ${excerpt}`));panel.append(label);options.push(box);}if(!options.length){panel.append(element('p','No exact excerpts were suggested.'));return;}const add=element('button','Add selected qualifications');add.type='button';add.addEventListener('click',async()=>{const chosen=options.filter(box=>box.checked&&!box.disabled);if(!chosen.length){notify('Select qualifications to add');return;}add.disabled=true;let added=0;const errors=[];for(const box of chosen){try{await api('/api/facts',{text:box.value});box.checked=false;box.disabled=true;added++;}catch(error){errors.push(error.message);}}await refresh().catch(()=>{});notify(errors.length?`Added ${added}; ${errors.length} failed: ${errors[0]}`:`Added ${added} qualifications`);add.disabled=false;});panel.append(add);}
try{const pending=JSON.parse(sessionStorage.getItem('waypoint-document-review') || 'null');if(pending){const panel=document.querySelector('#document-preview');panel.replaceChildren(element('h3',`Recovering document review: ${pending.name}`),element('p','Reviewing document locally…'));followDocumentReview(pending.task).then(result=>{panel.replaceChildren(element('h3',`Document review: ${pending.name}`));renderDocumentSuggestions(panel,result);}).catch(e=>{if(e.message==='Document review task not found')sessionStorage.removeItem('waypoint-document-review');panel.append(element('p',e.message,'review-label'));});}}catch(_){sessionStorage.removeItem('waypoint-document-review');}


try { const pending=JSON.parse(sessionStorage.getItem('waypoint-application-check') || 'null'); if(pending)followApplicationCheck(pending.task,pending.job).catch(e=>{if(e.message==='Application check not found')sessionStorage.removeItem('waypoint-application-check');notify(`${e.message}${pendingApplicationCheck()?' · Use Resume application check to retry.':''}`);renderJobs();}); } catch (_) { sessionStorage.removeItem('waypoint-application-check'); }

async function gmailStatus(){const state=await api('/api/gmail/status',{});document.querySelector('#gmail-info').textContent=state.connected?'Gmail credentials saved locally. In-app sending is not available yet.':state.secure_storage?'No Gmail account connected.':'Gmail connection requires Windows DPAPI storage.';}
async function followInboxStatus(id){const info=document.querySelector('#gmail-inbox-info');try{let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/gmail/inbox-status',{task_id:id});}while(result.status==='running');sessionStorage.removeItem('waypoint-gmail-inbox');if(result.status!=='complete')throw new Error(result.error || 'Inbox check failed');info.textContent=`Inbox: ${result.messages} messages · ${result.unseen} unread. No messages were opened.`;}catch(error){if(error.message==='Inbox status task not found')sessionStorage.removeItem('waypoint-gmail-inbox');info.textContent=error.message;}}
document.querySelector('#gmail-inbox-check').addEventListener('click',async event=>{const button=event.currentTarget,info=document.querySelector('#gmail-inbox-info');button.disabled=true;try{const started=await api('/api/gmail/inbox-start',{});sessionStorage.setItem('waypoint-gmail-inbox',started.task_id);info.textContent='Checking inbox counts…';await followInboxStatus(started.task_id);}catch(error){info.textContent=error.message;}finally{button.disabled=false;}});
const pendingInbox=sessionStorage.getItem('waypoint-gmail-inbox');if(pendingInbox)followInboxStatus(pendingInbox);
async function followGmailSelfTest(id){const info=document.querySelector('#gmail-self-test-info'),button=document.querySelector('#gmail-self-test');button.disabled=true;try{let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/gmail/self-test-status',{task_id:id});}while(result.status==='running');sessionStorage.removeItem('waypoint-gmail-self-test');info.textContent=result.status==='accepted'?'Gmail accepted the self-addressed test message. Check the inbox for delivery.':result.error || 'Test failed; check the mailbox before retrying.';}catch(error){if(error.message.startsWith('Gmail self-test not found'))sessionStorage.removeItem('waypoint-gmail-self-test');info.textContent=`${error.message} Check the mailbox before retrying.`;}finally{button.disabled=false;}}
document.querySelector('#gmail-self-test').addEventListener('click',async event=>{const button=event.currentTarget,info=document.querySelector('#gmail-self-test-info');button.disabled=true;try{const started=await api('/api/gmail/self-test-start',{reviewed:true});sessionStorage.setItem('waypoint-gmail-self-test',started.task_id);info.textContent='Sending the self-addressed test message…';await followGmailSelfTest(started.task_id);}catch(error){info.textContent=`${error.message} Check the mailbox before retrying.`;button.disabled=false;}});
