async function followGmailPassword(id){const info=document.querySelector('#gmail-info'),cancel=document.querySelector('#gmail-password-cancel');cancel.hidden=false;try{let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/gmail/password-status',{task_id:id});if(result.cancel_requested)info.textContent='Cancellation requested; waiting for the current network operation to finish.';}while(result.status==='running');sessionStorage.removeItem('waypoint-gmail-password');if(result.status!=='complete')throw new Error(result.error || 'Gmail connection failed');await gmailStatus();notify('Gmail authentication succeeded; no email was sent.');}catch(error){if(error.message==='Gmail connection not found')sessionStorage.removeItem('waypoint-gmail-password');info.textContent=error.message;}finally{cancel.hidden=true;cancel.disabled=false;}}
document.querySelector('#gmail-password-cancel').addEventListener('click',async event=>{const button=event.currentTarget,id=sessionStorage.getItem('waypoint-gmail-password');if(!id)return;button.disabled=true;try{await api('/api/gmail/password-cancel',{task_id:id});document.querySelector('#gmail-info').textContent='Cancellation requested; waiting for the current network operation to finish.';}catch(error){document.querySelector('#gmail-info').textContent=error.message;button.disabled=false;}});
document.querySelector('#gmail-password-connect').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{const started=await api('/api/gmail/password-start',{email:form.elements.email.value.trim(),password:form.elements.password.value});form.elements.password.value='';sessionStorage.setItem('waypoint-gmail-password',started.task_id);document.querySelector('#gmail-info').textContent='Checking Gmail authentication; no message will be sent.';await followGmailPassword(started.task_id);}catch(error){document.querySelector('#gmail-info').textContent=error.message;}finally{form.elements.password.value='';button.disabled=false;}});
const pendingGmailPassword=sessionStorage.getItem('waypoint-gmail-password');if(pendingGmailPassword)followGmailPassword(pendingGmailPassword);
async function followGmail(id){const info=document.querySelector('#gmail-info'),cancel=document.querySelector('#gmail-cancel');cancel.hidden=false;try{for(;;){const result=await api('/api/gmail/connect-status',{task_id:id});if(result.status==='complete'){sessionStorage.removeItem('waypoint-gmail-connect');await gmailStatus();break;}if(result.status==='failed'){sessionStorage.removeItem('waypoint-gmail-connect');throw new Error(result.error || 'Connection failed');}await new Promise(resolve=>setTimeout(resolve,1000));}}catch(e){info.textContent=e.message;if(e.message==='Gmail connection not found')sessionStorage.removeItem('waypoint-gmail-connect');}finally{cancel.hidden=true;}}
document.querySelector('#gmail-connect').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),file=form.elements.client.files[0];if(!file || file.size>32768){notify('Choose an OAuth JSON file no larger than 32 KiB');return;}button.disabled=true;try{const result=await api('/api/gmail/connect-start',{client_json:await file.text()});sessionStorage.setItem('waypoint-gmail-connect',result.task_id);document.querySelector('#gmail-info').textContent='Complete Google consent in your browser.';await followGmail(result.task_id);}catch(e){notify(e.message);}finally{button.disabled=false;form.reset();}});
document.querySelector('#gmail-cancel').addEventListener('click',async()=>{try{await api('/api/gmail/connect-cancel',{task_id:sessionStorage.getItem('waypoint-gmail-connect')});}catch(e){notify(e.message);}});
document.querySelector('#gmail-disconnect').addEventListener('click',async()=>{try{await api('/api/gmail/disconnect',{});await gmailStatus();notify('Saved Gmail credentials removed locally.');}catch(e){notify(e.message);}});
const pendingGmail=sessionStorage.getItem('waypoint-gmail-connect');if(pendingGmail)followGmail(pendingGmail);else gmailStatus().catch(()=>{});

async function storageStatus(){const result=await api('/api/storage/status',{});document.querySelector('#storage-info').textContent=`Active: ${result.active || 'unavailable'} · Configured: ${result.configured}`;document.querySelector('#storage-form').elements.path.value=result.configured;}
document.querySelector('#storage-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{await api('/api/storage/configure',{path:form.elements.path.value.trim()});await storageStatus();notify('Folder saved. Restart Waypoint to use it; existing data stays where it is.');}catch(e){notify(e.message);}finally{button.disabled=false;}});
storageStatus().catch(e=>{document.querySelector('#storage-info').textContent=e.message;});

const pendingConversion=sessionStorage.getItem('waypoint-conversion');updateConversionControl();if(pendingConversion)followConversion(pendingConversion).catch(conversionError);

try{const pending=JSON.parse(sessionStorage.getItem('waypoint-form-inspection') || 'null');if(pending)followFormInspection(pending.task,pending.job).then(()=>{if(pending.queued&&reviewQueue[0]===pending.job){reviewQueue.shift();saveReviewQueue();}}).catch(e=>{if(e.message==='Form inspection not found')sessionStorage.removeItem('waypoint-form-inspection');notify(e.message);}).finally(()=>{reviewQueueBusy=false;renderReviewQueue();});}catch(_){sessionStorage.removeItem('waypoint-form-inspection');reviewQueueBusy=false;}

function updateCandidateSelection(){document.querySelector('#candidate-selected-count').textContent=`${selectedCandidates.size} listings selected`;document.querySelector('#candidate-batch-start').disabled=candidateBatchRunning || (!candidateBatch && (selectedCandidates.size===0 || selectedCandidates.size>10));}
function searchCoverage(data){const reported=Number.isSafeInteger(data.results_reported)&&data.results_reported>=0?` of ${data.results_reported} provider results`:'';const unavailable=Number.isSafeInteger(data.unresponsive_engines)&&data.unresponsive_engines>=0?`${data.unresponsive_engines} ${data.unresponsive_engines===1?'engine':'engines'} reported unavailable`:'Provider did not report engine availability';return `${data.results_examined} examined${reported}${data.limited?' (not all returned results examined)':''} · ${unavailable}`;}
function webCandidate(item){const card=element('article','','web-candidate'),link=element('a',item.title),label=element('label','','candidate-select'),checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=selectedCandidates.has(item.url);checkbox.setAttribute('aria-label',`Select listing ${item.title}`);checkbox.addEventListener('change',()=>{if(checkbox.checked)selectedCandidates.set(item.url,{url:item.url,title:item.title});else selectedCandidates.delete(item.url);updateCandidateSelection();});label.append(checkbox,document.createTextNode(' Select for inspection'));card.append(label);link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link,element('p',item.snippet));if(Array.isArray(item.engines) && item.engines.length)card.append(element('p',`Search engines reported by provider: ${item.engines.join(', ')}`,'footnote'));if(item.published_date)card.append(element('p',`Provider-reported page date: ${item.published_date}`,'footnote'));card.append(element('p','Unverified link; inspect or open the page and review before applying.','footnote'));const inspect=element('button','Inspect and add');inspect.type='button';inspect.addEventListener('click',async()=>{inspect.disabled=true;try{const started=await api('/api/listing-inspect/start',{url:item.url});sessionStorage.setItem('waypoint-listing-inspection',started.task_id);notify('Inspecting listing in the background');await followListingInspection(started.task_id);}catch(e){notify(e.message);void offerListingRecovery(e.message);}finally{inspect.disabled=false;}});card.append(inspect);const add=element('button','Enter details manually');add.type='button';add.addEventListener('click',()=>{const form=document.querySelector('#manual-job-form');form.closest('details').open=true;const occupied=['url','title','employer','location','requisition_id','description'].some(name=>form.elements[name].value.trim());if(occupied && form.elements.url.value!==item.url){notify('Finish or clear the current manual job before choosing another result.');form.scrollIntoView({behavior:'smooth'});return;}form.elements.url.value=item.url;if(!form.elements.title.value.trim())form.elements.title.value=item.title;form.elements.employer.focus();form.scrollIntoView({behavior:'smooth'});});card.append(add);return card;}
let webSearchFollowing=false;async function followWebSearch(id){if(webSearchFollowing)return;webSearchFollowing=true;try{const panel=document.querySelector('#web-search-results');let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/web-search/status',{task_id:id});}while(result.status==='running');if(result.status!=='complete'){sessionStorage.removeItem('waypoint-web-search');throw new Error(result.error || 'Web search failed');}const data=result.data;panel.replaceChildren(element('p',`${data.results.length} candidate links · ${searchCoverage(data)}.`));for(const item of data.results)panel.append(webCandidate(item));}finally{webSearchFollowing=false;}}
async function recoverPendingWebSearch(){const pending=await api('/api/web-search/pending',{});if(!pending.task_id)return false;sessionStorage.setItem('waypoint-web-search',pending.task_id);document.querySelector('#web-search-results').replaceChildren(element('p','Resuming the pending search…'));await followWebSearch(pending.task_id);return true;}
document.querySelector('#web-search').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),panel=document.querySelector('#web-search-results');button.disabled=true;panel.replaceChildren(element('p','Searching…'));try{const result=await api('/api/web-search/start',{provider:form.elements.provider.value,query:form.elements.query.value,plan_digest:searchPlanBinding(form.elements.query)});sessionStorage.setItem('waypoint-web-search',result.task_id);await followWebSearch(result.task_id);}catch(e){panel.replaceChildren(element('p',e.message));try{await recoverPendingWebSearch();}catch(recoveryError){notify(`Could not resume the pending search: ${recoveryError.message}`);}}finally{button.disabled=false;}});
async function restoreWebSearch(){const button=document.querySelector('#web-search button');button.disabled=true;try{if(await recoverPendingWebSearch())return;const saved=sessionStorage.getItem('waypoint-web-search');if(saved)await followWebSearch(saved);}catch(error){if(error.message==='Web search not found')sessionStorage.removeItem('waypoint-web-search');else notify(`Could not restore the search: ${error.message}`);}finally{button.disabled=false;}}
void restoreWebSearch();

let webBatchRunning=false;
let webBatchPage=0;
function renderWebBatch(batch){
 const panel=document.querySelector('#web-search-batch-results'),pageSize=40,total=batch.groups.reduce((n,group)=>n+(Array.isArray(group.data?.results)?group.data.results.length:0),0),pages=Math.max(1,Math.ceil(total/pageSize));
 webBatchPage=Math.min(webBatchPage,pages-1);const start=webBatchPage*pageSize,end=start+pageSize;panel.replaceChildren();
 const controls=element('div','','multi-paging'),previous=element('button','Previous candidates'),next=element('button','Next candidates');previous.type=next.type='button';previous.disabled=webBatchPage===0;next.disabled=webBatchPage+1>=pages;
 previous.addEventListener('click',()=>{webBatchPage--;renderWebBatch(batch);});next.addEventListener('click',()=>{webBatchPage++;renderWebBatch(batch);});controls.append(previous,element('span',`Candidates ${total?start+1:0}–${Math.min(end,total)} of ${total}`),next);panel.append(controls);
 let offset=0;for(const group of batch.groups){const items=Array.isArray(group.data?.results)?group.data.results:[],visible=items.slice(Math.max(0,start-offset),Math.max(0,end-offset));offset+=items.length;if(!group.error && !visible.length && items.length)continue;panel.append(element('h4',`Search: ${group.query} · page ${group.page || 1}`));if(group.error){panel.append(element('p',group.error,'review-label'));continue;}const data=group.data;panel.append(element('p',`${data.results.length} new candidates · ${searchCoverage(data)}${data.previously_seen?` · ${data.previously_seen} already seen`:''}`,'footnote'));for(const item of visible)panel.append(webCandidate(item));}
}
async function followWebBatch(batch){if(webBatchRunning)return;webBatchRunning=true;const stop=document.querySelector('#web-search-batch-cancel'),status=document.querySelector('#web-search-batch-status');stop.hidden=false;renderWebBatch(batch);try{for(;;){await new Promise(resolve=>setTimeout(resolve,1000));const result=await api('/api/web-search/batch-status',{task_id:batch.task,acknowledged:batch.groups.length});status.textContent=`${result.processed} of ${result.total} search pages completed.`;if(Array.isArray(result.history)){batch.groups=result.history.map(item=>({query:item.query,page:item.page,data:item.data,error:item.error}));sessionStorage.setItem('waypoint-web-search-batch',JSON.stringify(batch));renderWebBatch(batch);}else if(result.query){batch.groups.push({query:result.query,page:result.page,data:result.data,error:result.error});sessionStorage.setItem('waypoint-web-search-batch',JSON.stringify(batch));renderWebBatch(batch);}if(result.status==='complete'){sessionStorage.removeItem('waypoint-web-search-batch');status.textContent=`${result.cancelled?'Stopped':'Finished'}: ${result.processed} of ${result.total} search pages.${result.limit_reached?' Reached the 600-candidate limit.':''} Links remain unverified.`;break;}if(result.status==='failed'){sessionStorage.removeItem('waypoint-web-search-batch');throw new Error(result.error || 'Batch search failed');}}}finally{webBatchRunning=false;stop.hidden=true;}}
document.querySelector('#web-search-batch').addEventListener('submit',async event=>{event.preventDefault();if(webBatchRunning)return;const form=event.currentTarget,queries=form.elements.queries.value.split(/\r?\n/).map(q=>q.trim()).filter(Boolean);if(!queries.length || queries.length>10){notify('Enter 1 to 10 search phrases');return;}const button=form.querySelector('button[type=submit]');button.disabled=true;try{const provider=document.querySelector('#web-search').elements.provider.value;const pages=Number(form.elements.pages.value);if(!Number.isInteger(pages)||pages<1||pages>5)throw new Error('Choose 1 to 5 pages per phrase');const started=await api('/api/web-search/batch-start',{provider,queries,pages});webBatchPage=0;const batch={task:started.task_id,groups:[]};sessionStorage.setItem('waypoint-web-search-batch',JSON.stringify(batch));await followWebBatch(batch);}catch(e){notify(e.message);}finally{button.disabled=false;}});
