try{const pending=JSON.parse(sessionStorage.getItem('waypoint-candidate-batch') || 'null');if(pending && Array.isArray(pending.items) && pending.items.length>0 && pending.items.length<=10 && Number.isInteger(pending.index) && pending.index>=0 && pending.index<=pending.items.length && Array.isArray(pending.events)){candidateBatch=pending;for(let node=document.querySelector('#candidate-batch-status').parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;void runCandidateBatch();}else sessionStorage.removeItem('waypoint-candidate-batch');}catch(_){sessionStorage.removeItem('waypoint-candidate-batch');}

async function followListingInspection(id){let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/listing-inspect/status',{task_id:id});}while(result.status==='running');sessionStorage.removeItem('waypoint-listing-inspection');if(result.status!=='complete')throw new Error(result.error || 'Listing needs manual review');await refresh();const note=(result.capture?.source_saved?' Listing source metadata was retained without screenshots.':'')+(result.capture?.structured_source && result.capture.structured_source!=='captured'?' Structured source was unavailable or exceeded the capture limit.':'');notify((result.capture && (!result.capture.saved || result.capture.complete===false)?'Listing saved; original page capture is incomplete or unavailable.':result.saved.existing?'This listing is already saved.':result.job?.extraction==='local_model'?'Listing extracted locally; review the details and application route.':'Structured listing added; review it and its application route.')+note);}
async function offerListingRecovery(message=''){
 const panel=document.querySelector('#listing-inspection-recovery');try{const pending=await api('/api/listing-inspect/pending',{});panel.replaceChildren();if(!pending.task_id)return;const id=pending.task_id;panel.append(element('p',message || 'A listing inspection is still pending. Resume it or discard the finished result.','review-label'));if(candidateBatch?.task===id){panel.append(element('p','This inspection belongs to the selected-listings queue. Use Resume inspections in that queue.','footnote'));return;}const retry=element('button','Resume listing inspection'),discard=element('button','Discard finished inspection');retry.type=discard.type='button';retry.addEventListener('click',async()=>{retry.disabled=discard.disabled=true;try{sessionStorage.setItem('waypoint-listing-inspection',id);await followListingInspection(id);panel.replaceChildren();}catch(error){await offerListingRecovery(error.message);}finally{retry.disabled=discard.disabled=false;}});discard.addEventListener('click',async()=>{retry.disabled=discard.disabled=true;try{await api('/api/listing-inspect/discard',{task_id:id});sessionStorage.removeItem('waypoint-listing-inspection');panel.replaceChildren();notify('Finished listing inspection discarded.');}catch(error){await offerListingRecovery(error.message);}finally{retry.disabled=discard.disabled=false;}});panel.append(retry,discard);}catch(error){panel.replaceChildren(element('p',`Could not check pending listing inspection: ${error.message}`,'review-label'));}}
