async function recoverReviewSession(){const panel=document.querySelector('#session-recovery');panel.replaceChildren(element('p','Checking the current review session…'));try{const result=await api('/api/form/session-status',{});reviewSessionChecked=true;if(!result.active && !pendingFormInspection() && typeof result.inspection?.task==='string' && typeof result.inspection?.job==='string'){sessionStorage.setItem('waypoint-form-inspection',JSON.stringify({task:result.inspection.task,job:result.inspection.job}));}const alreadyVisible=result.active&&activeReviewSession===result.session_id&&document.querySelector('#form-preview').childElementCount>0;activeReviewSession=result.active?result.session_id:null;panel.replaceChildren();if(result.active){const nav=pendingFormNavigation();if(nav?.job===result.job_id)sessionStorage.removeItem('waypoint-form-navigation');try{const pending=JSON.parse(sessionStorage.getItem('waypoint-form-inspection')||'null');if(pending?.job===result.job_id){if(pending.queued&&reviewQueue[0]===result.job_id){reviewQueue.shift();saveReviewQueue();}sessionStorage.removeItem('waypoint-form-inspection');}}catch(_){}}if(result.active&&!alreadyVisible){setWorkspaceView('applications');panel.append(element('p','An application review is still open. Resume or close it before opening the next queued job.','review-label'));const resume=element('button','Resume current review'),close=element('button','Close current review');resume.type=close.type='button';resume.addEventListener('click',async()=>{resume.disabled=close.disabled=true;try{const started=await api('/api/form/rescan-start',{session_id:result.session_id});sessionStorage.setItem('waypoint-form-navigation',JSON.stringify({task:started.task_id,job:result.job_id}));await followFormNavigation(started.task_id,result.job_id);}catch(error){panel.append(element('p',error.message,'review-label'));resume.disabled=close.disabled=false;await recoverReviewSession();}});close.addEventListener('click',async()=>{resume.disabled=close.disabled=true;try{await api('/api/form/close',{session_id:result.session_id});activeReviewSession=null;panel.replaceChildren();renderReviewQueue();}catch(error){panel.append(element('p',error.message,'review-label'));resume.disabled=close.disabled=false;}});panel.append(resume,close);}else if(!result.active && pendingFormNavigation()){const pending=pendingFormNavigation();setWorkspaceView('applications');panel.append(element('p','A form navigation is pending. Resume its status check.','review-label'));const retry=element('button','Resume pending navigation');retry.type='button';retry.addEventListener('click',async()=>{if(formNavigationFollowing){notify('Navigation is already being checked');return;}retry.disabled=true;try{await followFormNavigation(pending.task,pending.job);panel.replaceChildren();}catch(error){if(error.message==='Navigation task not found')sessionStorage.removeItem('waypoint-form-navigation');notify(error.message);await recoverReviewSession();}finally{retry.disabled=false;}});panel.append(retry);}else if(!result.active && pendingFormInspection()){const pending=pendingFormInspection();setWorkspaceView('applications');panel.append(element('p','A form inspection is pending. Resume its status check.','review-label'));const retry=element('button','Resume pending form inspection');retry.type='button';retry.addEventListener('click',async()=>{if(formInspectionFollowing){notify('The form inspection is already being checked');return;}retry.disabled=true;try{await followFormInspection(pending.task,pending.job);panel.replaceChildren();}catch(error){if(error.message==='Form inspection not found')sessionStorage.removeItem('waypoint-form-inspection');notify(error.message);await recoverReviewSession();}finally{retry.disabled=false;}});panel.append(retry);}renderReviewQueue();}catch(error){reviewSessionChecked=false;panel.replaceChildren(element('p',`Could not check the current review session: ${error.message}`,'review-label'));const retry=element('button','Retry session check');retry.type='button';retry.addEventListener('click',recoverReviewSession);panel.append(retry);renderReviewQueue();}}
