 const panel=element('div','','notice');panel.setAttribute('aria-live','polite');panel.append(element('p','Recovering local link suggestions…'));document.querySelector('#session-recovery').before(panel);
 try{let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/form/link-rank-status',{task_id:pending.task});if(result.session_unavailable)panel.firstElementChild.textContent='The review session ended or changed. Waiting for the local ranking to finish before releasing it.';}while(result.status==='running');sessionStorage.removeItem('waypoint-link-rank');if(result.status!=='complete')throw new Error(result.error || 'Link ranking failed');panel.replaceChildren(element('h3','Recovered link suggestions'),element('p','These suggestions describe an earlier page snapshot. Resume the review session and inspect the current page before choosing a link. Nothing was opened.','footnote'));if(!result.links?.length)panel.append(element('p','No likely application links were suggested.'));for(const link of result.links || [])panel.append(element('p',`${link.label || 'Unlabelled link'} · ${link.url}`));}
 catch(error){if(/not found|session expired/i.test(error.message))sessionStorage.removeItem('waypoint-link-rank');panel.replaceChildren(element('p',`Could not recover link suggestions: ${error.message}`,'review-label'));if(sessionStorage.getItem('waypoint-link-rank')){const retry=element('button','Retry recovering link suggestions');retry.type='button';retry.addEventListener('click',()=>{panel.remove();void recoverLinkRank();});panel.append(retry);}}finally{recoveringLinkRank=false;}
