let recoveringFormVision=false;
async function recoverFormVision(){
 if(recoveringFormVision)return;
 let pending;try{pending=JSON.parse(sessionStorage.getItem('waypoint-form-vision')||'null');}catch(_){sessionStorage.removeItem('waypoint-form-vision');return;}
 if(!pending || typeof pending.task!=='string' || typeof pending.session!=='string' || !Number.isSafeInteger(pending.segment) || pending.segment<0 || pending.segment>5){if(pending)sessionStorage.removeItem('waypoint-form-vision');return;}
 setWorkspaceView('applications');recoveringFormVision=true;
 const panel=element('div','','notice');panel.setAttribute('aria-live','polite');panel.append(element('p',`Recovering visual review for page segment ${pending.segment+1}…`));document.querySelector('#session-recovery').before(panel);
 try{let result;do{await new Promise(resolve=>setTimeout(resolve,1500));result=await api('/api/form/visual-review-status',{task_id:pending.task});}while(result.status==='running');sessionStorage.removeItem('waypoint-form-vision');if(result.status!=='complete')throw new Error(result.error || 'Visual review failed');panel.replaceChildren(element('h3',`Recovered visual review · segment ${pending.segment+1}`),element('p','This is one earlier screenshot, not a complete review of the current form. Resume the session, inspect the live page, and run a new full visual review. Model observations may be wrong.','review-label'));if(result.record_saved===false)panel.append(element('p','The result could not be saved in the application record.','review-label'));if(result.freshness_record_saved===false)panel.append(element('p','This fresh-capture check was not saved to the application record.','review-label'));if(['changed','unavailable'].includes(result.visual_freshness))await refresh().catch(()=>{});if(result.visual_freshness==='changed')panel.append(element('p','This page segment changed after the captured image; inspect the live form again. Animations can also cause this warning.','review-label'));else if(result.visual_freshness==='unavailable')panel.append(element('p','A fresh page capture was unavailable. Inspect the live form manually.','review-label'));const review=result.visual_review;if(!review || !Array.isArray(review.observations))throw new Error('Invalid visual review result');if(pending.comparisons_truncated)panel.append(element('p','More than 200 supported fields were filled; some were not included in this comparison.','review-label'));if(review.observation_limit_reached===true){panel.append(element('p','This segment reached the 20-observation limit; additional fields may have been missed. Inspect the live page manually.','review-label'));await refresh().catch(()=>{});}if(!review.observations.length)panel.append(element('p','No fields were transcribed from this segment.'));for(const item of review.observations)panel.append(element('p',`${item.label}: ${item.visible_value}`));if(Array.isArray(review.comparisons)){panel.append(element('p','Comparison for this segment only; verify every field on the live form.','footnote'));for(const item of review.comparisons){const status={matches_transcription:'transcription matches reviewed answer',differs_from_transcription:'transcription differs from reviewed answer',unobserved:'not uniquely observed'}[item.status] || 'comparison unavailable';panel.append(element('p',`${item.label}: ${status}`,'review-label'));}}}
 catch(error){if(/not found|session expired|no longer current/i.test(error.message))sessionStorage.removeItem('waypoint-form-vision');panel.replaceChildren(element('p',`Could not recover visual review: ${error.message}. Inspect the current form manually.`,'review-label'));if(sessionStorage.getItem('waypoint-form-vision')){const retry=element('button','Retry recovering visual review');retry.type='button';retry.addEventListener('click',()=>{panel.remove();void recoverFormVision();});panel.append(retry);}await refresh().catch(()=>{});}finally{recoveringFormVision=false;}
}
